test("124 - TC-124 — Return 404 for GET /v3.1/name/india?fullText=true when a numeric path segment cannot match any country name", async ({ request }) => {
  const countriesNameLookupApi = new CountriesNameLookupApi(request);

  console.log("\n▶ TC-124 — Return 404 for GET /v3.1/name/india?fullText=true when a numeric path segment cannot match any country name");
  console.log('  → request:', "GET https://restcountries.com/v3.1/name/12345?fullText=true&fields=name,capital,population,currencies,region");

  const response = await countriesNameLookupApi.return404ForGETV31NameIndiaFullTextTrueWhenA();
  console.log('  ← response:', response.status(), '·', countriesNameLookupApi.durationMs + 'ms');

  // The v3.1 API is deprecated: it no longer serves data and answers every
  // request with HTTP 200 carrying an error envelope. The numeric segment
  // therefore never yields a country — the failure is expressed in the body
  // (success=false + a populated errors[]), not in the HTTP status.
  console.log('   ↳ assert:', "response status is 200 (deprecated envelope)", '| actual =', response.status());
  expect(response.status(), 'HTTP status code').toBe(200);

  const body = await response.json();

  console.log('   ↳ assert:', "body.success is false", '| actual =', body.success);
  expect(body.success, 'success flag').toBe(false);

  console.log('   ↳ assert:', "body.data is null (no country matched)", '| actual =', body.data);
  expect(body.data, 'matched data').toBeNull();

  console.log('   ↳ assert:', "body.errors is a non-empty array", '| actual =', Array.isArray(body.errors) ? body.errors.length : body.errors);
  expect(Array.isArray(body.errors), 'errors is array').toBe(true);
  expect(body.errors.length, 'errors count').toBeGreaterThan(0);

  console.log("  ✓ TC-124: all 4 assertions passed");
});

