// @flow 6 steps — values extracted by one step feed the next.
test("166 - TC-166 — Verify the full posts lifecycle: create → read → update → verify → delete → confirm 404", async ({ request }) => {
  const postsFlowsApi = new PostsFlowsApi(request);
  const vars: Vars = {};

  console.log("\n▶ TC-166 — Verify the full posts lifecycle: create → read → update → verify → delete → confirm 404");

  await test.step("1. create — POST https://jsonplaceholder.typicode.com/posts", async () => {
    console.log('  → step 1:', "create · POST https://jsonplaceholder.typicode.com/posts");
    const response = await postsFlowsApi.createPosts();
    console.log('  ← response:', response.status(), '·', postsFlowsApi.durationMs + 'ms');
    const body = await postsFlowsApi.json(response);
    console.log('     ↳ assert:', "response status is 200", '| actual =', response.status());
    expect(response.status(), 'HTTP status code').toBe(200);
    console.log('     ↳ assert:', "JSON \"id\" is present", '| actual =', getPath(body, "id"));
    expect(getPath(body, "id"), "property \"id\" should exist").toBeDefined();
    console.log('     ↳ assert:', "JSON \"title\" equals \"QA Automation Post\"", '| actual =', getPath(body, "title"));
    expect(getPath(body, "title"), "property \"title\"").toEqual("QA Automation Post");
    console.log('     ↳ assert:', "JSON \"userId\" equals 1", '| actual =', getPath(body, "userId"));
    expect(getPath(body, "userId"), "property \"userId\"").toEqual(1);
    vars["postId"] = String(getPath(body, "id") ?? '');
    expect(vars["postId"], "step 1 must yield \"postId\" from \"id\"").not.toBe('');
    console.log('     ↳ extract:', "postId = " + vars["postId"]);
  });

  await test.step("2. read — GET https://jsonplaceholder.typicode.com/posts/{{postId}}", async () => {
    console.log('  → step 2:', "read · GET https://jsonplaceholder.typicode.com/posts/{{postId}}");
    const response = await postsFlowsApi.readPosts(vars);
    console.log('  ← response:', response.status(), '·', postsFlowsApi.durationMs + 'ms');
    const body = await postsFlowsApi.json(response);
    console.log('     ↳ assert:', "response status is 200", '| actual =', response.status());
    expect(response.status(), 'HTTP status code').toBe(200);
    console.log('     ↳ assert:', "JSON \"id\" is present", '| actual =', getPath(body, "id"));
    expect(getPath(body, "id"), "property \"id\" should exist").toBeDefined();
  });

  await test.step("3. update — PUT https://jsonplaceholder.typicode.com/posts/{{postId}}", async () => {
    console.log('  → step 3:', "update · PUT https://jsonplaceholder.typicode.com/posts/{{postId}}");
    const response = await postsFlowsApi.updatePosts(vars);
    console.log('  ← response:', response.status(), '·', postsFlowsApi.durationMs + 'ms');
    const body = await postsFlowsApi.json(response);
    console.log('     ↳ assert:', "response status is 200", '| actual =', response.status());
    expect(response.status(), 'HTTP status code').toBe(200);
    console.log('     ↳ assert:', "JSON \"title\" equals \"Updated Title\"", '| actual =', getPath(body, "title"));
    expect(getPath(body, "title"), "property \"title\"").toEqual("Updated Title");
    console.log('     ↳ assert:', "JSON \"body\" equals \"Updated body\"", '| actual =', getPath(body, "body"));
    expect(getPath(body, "body"), "property \"body\"").toEqual("Updated body");
  });

  await test.step("4. verify — GET https://jsonplaceholder.typicode.com/posts/{{postId}}", async () => {
    console.log('  → step 4:', "verify · GET https://jsonplaceholder.typicode.com/posts/{{postId}}");
    const response = await postsFlowsApi.readPosts(vars);
    console.log('  ← response:', response.status(), '·', postsFlowsApi.durationMs + 'ms');
    const body = await postsFlowsApi.json(response);
    console.log('     ↳ assert:', "response status is 200", '| actual =', response.status());
    expect(response.status(), 'HTTP status code').toBe(200);
    console.log('     ↳ assert:', "JSON \"id\" is present", '| actual =', getPath(body, "id"));
    expect(getPath(body, "id"), "property \"id\" should exist").toBeDefined();
  });

  await test.step("5. delete — DELETE https://jsonplaceholder.typicode.com/posts/{{postId}}", async () => {
    console.log('  → step 5:', "delete · DELETE https://jsonplaceholder.typicode.com/posts/{{postId}}");
    const response = await postsFlowsApi.deletePosts(vars);
    console.log('  ← response:', response.status(), '·', postsFlowsApi.durationMs + 'ms');
    console.log('     ↳ assert:', "response status is 200", '| actual =', response.status());
    expect(response.status(), 'HTTP status code').toBe(200);
  });

  await test.step("6. confirm-gone — GET https://jsonplaceholder.typicode.com/posts/{{postId}}", async () => {
    console.log('  → step 6:', "confirm-gone · GET https://jsonplaceholder.typicode.com/posts/{{postId}}");
    const response = await postsFlowsApi.readPosts(vars);
    console.log('  ← response:', response.status(), '·', postsFlowsApi.durationMs + 'ms');
    console.log('     ↳ assert:', "response status is 404", '| actual =', response.status());
    expect(response.status(), 'HTTP status code').toBe(404);
  });

  console.log("  ✓ TC-166: all 13 assertions across 6 steps passed");
});
